(function(){
  'use strict';

  // State
  let tasks = JSON.parse(localStorage.getItem('taskflow_tasks') || '[]');
  let currentFilter = 'all';
  let selectedPriority = 'medium';

  // DOM Elements
  const screens = document.querySelectorAll('.screen');
  const tabItems = document.querySelectorAll('.tab-item');
  const taskList = document.getElementById('taskList');
  const emptyState = document.getElementById('emptyState');
  const addTaskBtn = document.getElementById('addTaskBtn');
  const backBtn = document.getElementById('backBtn');
  const taskForm = document.getElementById('taskForm');
  const filterChips = document.querySelectorAll('.chip');
  const priorityBtns = document.querySelectorAll('.priority-btn');
  const clearAllBtn = document.getElementById('clearAllBtn');
  const statusTime = document.getElementById('statusTime');

  // Update status bar time
  function updateTime() {
    const now = new Date();
    const h = now.getHours();
    const m = now.getMinutes().toString().padStart(2, '0');
    statusTime.textContent = h + ':' + m;
  }
  updateTime();
  setInterval(updateTime, 30000);

  // Navigation
  function showScreen(screenId) {
    screens.forEach(s => s.classList.remove('active'));
    document.getElementById(screenId).classList.add('active');
    tabItems.forEach(t => {
      t.classList.toggle('active', t.dataset.screen === screenId);
    });
    if (screenId === 'profileScreen') updateProfile();
    if (screenId === 'homeScreen') renderTasks();
  }

  tabItems.forEach(tab => {
    tab.addEventListener('click', () => showScreen(tab.dataset.screen));
  });

  addTaskBtn.addEventListener('click', () => showScreen('addScreen'));
  backBtn.addEventListener('click', () => showScreen('homeScreen'));

  // Filter chips
  filterChips.forEach(chip => {
    chip.addEventListener('click', () => {
      filterChips.forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      currentFilter = chip.dataset.filter;
      renderTasks();
    });
  });

  // Priority selector
  priorityBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      priorityBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      selectedPriority = btn.dataset.priority;
    });
  });

  // Save tasks
  function saveTasks() {
    localStorage.setItem('taskflow_tasks', JSON.stringify(tasks));
  }

  // Add task
  taskForm.addEventListener('submit', function(e) {
    e.preventDefault();
    const title = document.getElementById('taskTitle').value.trim();
    const description = document.getElementById('taskDescription').value.trim();
    const category = document.getElementById('taskCategory').value;

    if (!title) return;

    const task = {
      id: Date.now().toString(),
      title: title,
      description: description,
      priority: selectedPriority,
      category: category,
      completed: false,
      createdAt: new Date().toISOString()
    };

    tasks.unshift(task);
    saveTasks();

    // Reset form
    taskForm.reset();
    priorityBtns.forEach(b => b.classList.remove('active'));
    document.querySelector('.priority-btn[data-priority="medium"]').classList.add('active');
    selectedPriority = 'medium';

    showScreen('homeScreen');
  });

  // Toggle task completion
  function toggleTask(id) {
    const task = tasks.find(t => t.id === id);
    if (task) {
      const card = document.querySelector('[data-task-id="' + id + '"]');
      if (card) {
        card.classList.add('completing');
        setTimeout(() => {
          task.completed = !task.completed;
          saveTasks();
          renderTasks();
          updateStats();
        }, 200);
      } else {
        task.completed = !task.completed;
        saveTasks();
        renderTasks();
        updateStats();
      }
    }
  }

  // Delete task
  function deleteTask(id) {
    const card = document.querySelector('[data-task-id="' + id + '"]');
    if (card) {
      card.style.transform = 'translateX(-100%)';
      card.style.opacity = '0';
      setTimeout(() => {
        tasks = tasks.filter(t => t.id !== id);
        saveTasks();
        renderTasks();
        updateStats();
      }, 250);
    } else {
      tasks = tasks.filter(t => t.id !== id);
      saveTasks();
      renderTasks();
      updateStats();
    }
  }

  // Render tasks
  function renderTasks() {
    let filtered = tasks;
    if (currentFilter === 'pending') filtered = tasks.filter(t => !t.completed);
    if (currentFilter === 'completed') filtered = tasks.filter(t => t.completed);

    if (filtered.length === 0) {
      taskList.innerHTML = '';
      taskList.appendChild(emptyState);
      emptyState.style.display = 'flex';
    } else {
      taskList.innerHTML = '';
      filtered.forEach(task => {
        const card = document.createElement('div');
        card.className = 'task-card';
        card.dataset.taskId = task.id;
        card.dataset.priority = task.priority;
        card.style.transition = 'transform .25s ease, opacity .25s ease';

        const checkboxClass = 'task-checkbox' + (task.completed ? ' checked' : '');
        const titleClass = 'task-title' + (task.completed ? ' completed' : '');

        let descriptionHtml = '';
        if (task.description) {
          descriptionHtml = '<p class="task-description">' + escapeHtml(task.description) + '</p>';
        }

        card.innerHTML = 
          '<div class="' + checkboxClass + '" data-toggle="' + task.id + '">' +
            '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>' +
          '</div>' +
          '<div class="task-info">' +
            '<div class="' + titleClass + '">' + escapeHtml(task.title) + '</div>' +
            descriptionHtml +
            '<div class="task-meta">' +
              '<span class="task-category">' + task.category + '</span>' +
            '</div>' +
          '</div>' +
          '<button class="task-delete" data-delete="' + task.id + '" aria-label="Delete task">' +
            '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>' +
          '</button>';

        taskList.appendChild(card);
      });
    }

    updateStats();
  }

  // Event delegation for task actions
  taskList.addEventListener('click', function(e) {
    const toggleEl = e.target.closest('[data-toggle]');
    if (toggleEl) {
      toggleTask(toggleEl.dataset.toggle);
      return;
    }
    const deleteEl = e.target.closest('[data-delete]');
    if (deleteEl) {
      deleteTask(deleteEl.dataset.delete);
      return;
    }
  });

  // Update stats
  function updateStats() {
    const total = tasks.length;
    const completed = tasks.filter(t => t.completed).length;
    const pending = total - completed;

    document.getElementById('totalTasks').textContent = total;
    document.getElementById('completedTasks').textContent = completed;
    document.getElementById('pendingTasks').textContent = pending;
  }

  // Update profile
  function updateProfile() {
    const total = tasks.length;
    const completed = tasks.filter(t => t.completed).length;
    const rate = total > 0 ? Math.round((completed / total) * 100) : 0;

    document.getElementById('profileTotal').textContent = total;
    document.getElementById('profileCompleted').textContent = completed;
    document.getElementById('profileRate').textContent = rate + '%';

    const progressBar = document.getElementById('progressBar');
    progressBar.style.width = rate + '%';
    document.getElementById('progressText').textContent = completed + ' of ' + total + ' tasks completed';
  }

  // Clear all tasks
  clearAllBtn.addEventListener('click', function() {
    if (tasks.length === 0) return;
    if (confirm('Are you sure you want to delete all tasks? This cannot be undone.')) {
      tasks = [];
      saveTasks();
      updateProfile();
      renderTasks();
    }
  });

  // Escape HTML
  function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // Initial render
  renderTasks();
  updateStats();
})();

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root{
  --accent:#4F46E5;
  --accent-light:#EEF2FF;
  --accent-dark:#3730A3;
  --bg:#f8fafc;
  --card-bg:#fff;
  --text-primary:#0f172a;
  --text-secondary:#64748b;
  --border:#e2e8f0;
  --shadow:0 1px 3px rgba(15,23,42,.08),0 1px 2px rgba(15,23,42,.04);
  --shadow-md:0 4px 6px rgba(15,23,42,.07),0 2px 4px rgba(15,23,42,.04);
  --radius:12px;
  --priority-low:#10b981;
  --priority-medium:#f59e0b;
  --priority-high:#ef4444;
}

html{font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;font-size:16px;line-height:1.65;color:var(--text-primary);background:#1e293b}

body{display:flex;justify-content:center;align-items:center;min-height:100vh;padding:16px}

.phone-frame{width:375px;max-width:100%;height:812px;max-height:100vh;background:var(--bg);border-radius:40px;overflow:hidden;display:flex;flex-direction:column;position:relative;box-shadow:0 25px 50px rgba(0,0,0,.25)}

.status-bar{height:44px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;flex-shrink:0;background:var(--card-bg);border-bottom:1px solid var(--border)}

.status-time{font-size:14px;font-weight:600}

.status-icons{display:flex;gap:6px;color:var(--text-primary)}

.app-content{flex:1;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch}

.screen{display:none;padding:16px 16px 24px;min-height:100%;animation:fadeIn .25s ease}

.screen.active{display:block}

@keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}

.page-header{padding:20px 0 16px}

.page-header h1{font-size:clamp(2rem,6vw,2.5rem);font-weight:800;letter-spacing:-.04em;line-height:1.1;color:var(--text-primary)}

.subtitle{color:var(--text-secondary);font-size:.875rem;margin-top:4px}

.stats-row{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:24px}

.stat-card{background:var(--card-bg);border:1px solid var(--border);border-radius:var(--radius);padding:16px 12px;text-align:center;box-shadow:var(--shadow)}

.stat-number{display:block;font-size:1.75rem;font-weight:800;color:var(--accent);line-height:1.2}

.stat-label{font-size:.75rem;color:var(--text-secondary);font-weight:500;text-transform:uppercase;letter-spacing:.05em}

.section-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}

.section-header h2{font-size:1.125rem;font-weight:700}

.btn-icon{width:44px;height:44px;display:flex;align-items:center;justify-content:center;border:none;background:var(--accent);color:#fff;border-radius:50%;cursor:pointer;box-shadow:var(--shadow-md);transition:transform .15s,background .15s}

.btn-icon:active{transform:scale(.92);background:var(--accent-dark)}

.filter-chips{display:flex;gap:8px;margin-bottom:16px;overflow-x:auto;padding-bottom:4px}

.chip{height:36px;padding:0 16px;border-radius:20px;border:1px solid var(--border);background:var(--card-bg);color:var(--text-secondary);font-size:.8125rem;font-weight:600;cursor:pointer;white-space:nowrap;transition:all .15s}

.chip.active{background:var(--accent);color:#fff;border-color:var(--accent)}

.chip:active{transform:scale(.95)}

.task-list{display:flex;flex-direction:column;gap:8px;padding-bottom:16px}

.empty-state{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:48px 16px;text-align:center;color:var(--text-secondary);gap:12px}

.empty-state p{font-size:.875rem}

.task-card{background:var(--card-bg);border:1px solid var(--border);border-radius:var(--radius);padding:14px 16px;box-shadow:var(--shadow);display:flex;align-items:flex-start;gap:12px;transition:transform .15s,opacity .3s;position:relative;overflow:hidden}

.task-card.completing{transform:scale(.96);opacity:.5}

.task-card::before{content:'';position:absolute;left:0;top:0;bottom:0;width:4px}

.task-card[data-priority="low"]::before{background:var(--priority-low)}
.task-card[data-priority="medium"]::before{background:var(--priority-medium)}
.task-card[data-priority="high"]::before{background:var(--priority-high)}

.task-checkbox{width:24px;height:24px;border-radius:50%;border:2px solid var(--border);flex-shrink:0;cursor:pointer;display:flex;align-items:center;justify-content:center;margin-top:2px;transition:all .2s}

.task-checkbox.checked{background:var(--accent);border-color:var(--accent)}

.task-checkbox.checked svg{opacity:1}

.task-checkbox svg{opacity:0;transition:opacity .2s}

.task-info{flex:1;min-width:0}

.task-title{font-size:.9375rem;font-weight:600;line-height:1.3;word-break:break-word}

.task-title.completed{text-decoration:line-through;color:var(--text-secondary)}

.task-meta{display:flex;align-items:center;gap:8px;margin-top:4px}

.task-category{font-size:.6875rem;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--accent);background:var(--accent-light);padding:2px 8px;border-radius:4px}

.task-description{font-size:.8125rem;color:var(--text-secondary);margin-top:4px;line-height:1.4;word-break:break-word}

.task-delete{width:32px;height:32px;border:none;background:transparent;color:var(--text-secondary);cursor:pointer;display:flex;align-items:center;justify-content:center;border-radius:8px;flex-shrink:0;transition:all .15s}

.task-delete:active{background:#fef2f2;color:var(--priority-high)}

/* Add Screen */
.screen-top-bar{display:flex;align-items:center;justify-content:space-between;height:44px;margin-bottom:16px}

.screen-top-bar h2{font-size:1.125rem;font-weight:700}

.btn-back{width:44px;height:44px;display:flex;align-items:center;justify-content:center;border:none;background:transparent;color:var(--text-primary);cursor:pointer;border-radius:var(--radius)}

.btn-back:active{background:var(--accent-light)}

.task-form{display:flex;flex-direction:column;gap:20px}

.form-group{display:flex;flex-direction:column;gap:6px}

.form-group label{font-size:.8125rem;font-weight:600;color:var(--text-secondary);text-transform:uppercase;letter-spacing:.04em}

.form-group input,.form-group textarea,.form-group select{height:44px;padding:0 14px;border:1px solid var(--border);border-radius:8px;font-size:.9375rem;font-family:inherit;color:var(--text-primary);background:var(--card-bg);outline:none;transition:border-color .2s,box-shadow .2s}

.form-group textarea{height:auto;padding:12px 14px;resize:none}

.form-group select{appearance:none;background-image:url("data:image/svg+xml,%3Csvg width='12' height='12' viewBox='0 0 24 24' fill='none' stroke='%2364748b' stroke-width='2.5'%3E%3Cpolyline points='6 9 12 15 18 9'/%3E%3C/svg%3E");background-repeat:no-repeat;background-position:right 14px center}

.form-group input:focus,.form-group textarea:focus,.form-group select:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(79,70,229,.15)}

.priority-selector{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}

.priority-btn{height:44px;border:1px solid var(--border);border-radius:8px;background:var(--card-bg);font-size:.8125rem;font-weight:600;font-family:inherit;cursor:pointer;transition:all .15s;color:var(--text-secondary)}

.priority-btn:active{transform:scale(.96)}

.priority-btn.active[data-priority="low"]{background:var(--priority-low);color:#fff;border-color:var(--priority-low)}
.priority-btn.active[data-priority="medium"]{background:var(--priority-medium);color:#fff;border-color:var(--priority-medium)}
.priority-btn.active[data-priority="high"]{background:var(--priority-high);color:#fff;border-color:var(--priority-high)}

.btn-primary{height:48px;border:none;border-radius:8px;background:var(--accent);color:#fff;font-size:1rem;font-weight:600;font-family:inherit;cursor:pointer;box-shadow:var(--shadow-md);transition:all .15s;margin-top:8px}

.btn-primary:active{transform:scale(.97);background:var(--accent-dark)}

/* Profile Screen */
.profile-card{background:var(--card-bg);border:1px solid var(--border);border-radius:var(--radius);padding:24px;text-align:center;box-shadow:var(--shadow);margin-bottom:16px}

.avatar{width:64px;height:64px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;margin:0 auto 12px}

.profile-card h3{font-size:1.125rem;font-weight:700}

.profile-email{color:var(--text-secondary);font-size:.8125rem;margin-top:2px}

.profile-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px}

.profile-stat-item{background:var(--card-bg);border:1px solid var(--border);border-radius:var(--radius);padding:16px 8px;text-align:center;box-shadow:var(--shadow)}

.profile-stat-value{display:block;font-size:1.5rem;font-weight:800;color:var(--accent);line-height:1.2}

.profile-stat-label{font-size:.6875rem;color:var(--text-secondary);font-weight:500}

.progress-section{background:var(--card-bg);border:1px solid var(--border);border-radius:var(--radius);padding:20px;box-shadow:var(--shadow);margin-bottom:24px}

.progress-section h3{font-size:.9375rem;font-weight:700;margin-bottom:12px}

.progress-bar-container{height:8px;background:var(--accent-light);border-radius:4px;overflow:hidden}

.progress-bar{height:100%;background:var(--accent);border-radius:4px;transition:width .5s ease}

.progress-text{font-size:.8125rem;color:var(--text-secondary);margin-top:8px}

.btn-danger{width:100%;height:48px;border:1px solid var(--priority-high);border-radius:8px;background:transparent;color:var(--priority-high);font-size:.9375rem;font-weight:600;font-family:inherit;cursor:pointer;transition:all .15s}

.btn-danger:active{background:#fef2f2;transform:scale(.97)}

/* Tab Bar */
.tab-bar{height:60px;display:flex;align-items:center;justify-content:space-around;background:var(--card-bg);border-top:1px solid var(--border);flex-shrink:0;padding-bottom:env(safe-area-inset-bottom,0)}

.tab-item{display:flex;flex-direction:column;align-items:center;gap:2px;border:none;background:transparent;color:var(--text-secondary);cursor:pointer;padding:6px 16px;font-family:inherit;min-height:44px;justify-content:center;transition:color .15s;-webkit-tap-highlight-color:transparent}

.tab-item span{font-size:.6875rem;font-weight:600}

.tab-item.active{color:var(--accent)}

.tab-item:active{opacity:.7}

/* Scrollbar */
.app-content::-webkit-scrollbar{width:0;display:none}

/* Responsive for actual mobile */
@media (max-width:400px){
  .phone-frame{border-radius:0;height:100vh;max-height:100vh;width:100%}
  body{padding:0}
}
